import{_ as o,o as a,c as e,a5 as r}from"./chunks/framework.D47SInms.js";const u=JSON.parse('{"title":"Stair mode not moving","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/troubleshooting/stair-mode-not-moving.md","filePath":"manual/troubleshooting/stair-mode-not-moving.md","lastUpdated":1791600043000}'),s={name:"manual/troubleshooting/stair-mode-not-moving.md"};function n(i,t,h,d,l,m){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="stair-mode-not-moving" tabindex="-1">Stair mode not moving <a class="header-anchor" href="#stair-mode-not-moving" aria-label="Permalink to &quot;Stair mode not moving&quot;">​</a></h1><p>You push the joystick in stair mode and the robot does not walk forward. The most common cause is that camera data is not coming through.</p><h2 id="first-checks" tabindex="-1">First checks <a class="header-anchor" href="#first-checks" aria-label="Permalink to &quot;First checks {#first-checks}&quot;">​</a></h2><ul><li>Confirm on screen that the mode actually changed to stair mode.</li><li>Confirm you are using the <strong>L stick</strong>.</li><li>Confirm <strong>camera video is coming through normally</strong>.</li></ul><h2 id="r-stick" tabindex="-1">Pushing the R stick forward does not move the robot <a class="header-anchor" href="#r-stick" aria-label="Permalink to &quot;Pushing the R stick forward does not move the robot {#r-stick}&quot;">​</a></h2><p><strong>Cause:</strong> In stair mode, forward and backward are handled by the <strong>L stick</strong>. This is by design, not a fault.</p><p><strong>Fix:</strong> Use the controls below.</p><table tabindex="0"><thead><tr><th>Control</th><th>Action</th></tr></thead><tbody><tr><td>L stick forward / back</td><td>Walk forward / backward</td></tr><tr><td>L stick left / right</td><td>Strafe</td></tr><tr><td>R stick left / right</td><td>Turn in place</td></tr></tbody></table><p>See <a href="/RBQ/nightly/manual/gui/motion-commands.html">Basic Motion Commands</a> for the controls of each mode.</p><h2 id="no-camera" tabindex="-1">Without camera video the robot does not move <a class="header-anchor" href="#no-camera" aria-label="Permalink to &quot;Without camera video the robot does not move {#no-camera}&quot;">​</a></h2><p><strong>Cause:</strong> Stair mode works from camera data. If there is no camera video, the robot does not move however far you push the joystick.</p><p><strong>Fix:</strong> Tap the status light next to the logo in the control home&#39;s top bar and check the <strong>Vision</strong> row of <strong>Overall system status</strong>. If no video is coming through, work through <a href="/RBQ/nightly/manual/troubleshooting/no-camera-view.html">No camera view</a> first.</p><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck? {#still-stuck}&quot;">​</a></h2><p>Open <strong><a href="/RBQ/nightly/manual/gui/logs.html#real-time">Logs → Real Time</a></strong> and send us the messages logged at the moment you pressed the stair mode button.</p><p><strong>→ <a href="/RBQ/nightly/manual/support/">Contact us</a></strong></p>',15)])])}const g=o(s,[["render",n]]);export{u as __pageData,g as default};
